### Implementation

Create a single consolidated program file or split the code into separate files matching the namespaces.

#### 1. Models & Common Types (`CloudInfrastructureProvisioner.Models`)

```csharp
using System;
using System.Collections.Generic;

namespace CloudInfrastructureProvisioner.Models
{
    public class ResourceDefinition
    {
        public string Id { get; set; } = string.Empty;
        public string Type { get; set; } = string.Empty;
        public Dictionary<string, object> Properties { get; set; } = new(StringComparer.OrdinalIgnoreCase);
        public List<string> Dependencies { get; set; } = new();
    }

    public record DeploymentResult(
        string ResourceId,
        string Type,
        bool Success,
        TimeSpan Duration,
        Dictionary<string, object> OutputProperties,
        string? ErrorMessage = null
    );

    public class DependencyException : Exception
    {
        public DependencyException(string message) : base(message) { }
    }

    public class CircularDependencyException : DependencyException
    {
        public CircularDependencyException(string message) : base(message) { }
    }
}
```

#### 2. Declarative Resource Parser (`CloudInfrastructureProvisioner.Parser`)

This component takes the raw declarative definition string, validates structural properties (such as checking for empty parameters or ID conflicts), and turns them into strongly typed models.

```csharp
using System;
using System.Collections.Generic;
using System.Linq;
using System.Text.Json;
using CloudInfrastructureProvisioner.Models;

namespace CloudInfrastructureProvisioner.Parser
{
    public class ResourceParser
    {
        private static readonly JsonSerializerOptions SerializerOptions = new()
        {
            PropertyNameCaseInsensitive = true,
            AllowTrailingCommas = true,
            ReadCommentHandling = JsonCommentHandling.Skip
        };

        public static List<ResourceDefinition> Parse(string json)
        {
            if (string.IsNullOrWhiteSpace(json))
            {
                throw new ArgumentException("Infrastructure configuration JSON cannot be null or empty.");
            }

            try
            {
                var resources = JsonSerializer.Deserialize<List<ResourceDefinition>>(json, SerializerOptions);
                if (resources == null)
                {
                    throw new JsonException("Parsed configuration returned empty list.");
                }

                ValidateDefinitions(resources);
                return resources;
            }
            catch (JsonException ex)
            {
                throw new FormatException($"Invalid infrastructure JSON structure: {ex.Message}", ex);
            }
        }

        private static void ValidateDefinitions(List<ResourceDefinition> resources)
        {
            var uniqueIds = new HashSet<string>(StringComparer.OrdinalIgnoreCase);

            foreach (var res in resources)
            {
                if (string.IsNullOrWhiteSpace(res.Id))
                {
                    throw new FormatException("Resource configurations must contain a non-empty, unique 'Id' field.");
                }

                if (string.IsNullOrWhiteSpace(res.Type))
                {
                    throw new FormatException($"Resource with ID '{res.Id}' must specify a valid 'Type'.");
                }

                if (!uniqueIds.Add(res.Id))
                {
                    throw new InvalidOperationException($"Duplicate resource ID detected: '{res.Id}' is declared more than once.");
                }
            }
        }
    }
}
```

#### 3. Dependency Graph Resolver (`CloudInfrastructureProvisioner.Resolver`)

This module evaluates resource declarations to detect missing links or recursive cycles. It performs a topological sort using DFS-based **three-state coloring** for cycle tracing, and then outputs a logical linear sorting or validates dependency integrity.

```csharp
using System;
using System.Collections.Generic;
using System.Linq;
using CloudInfrastructureProvisioner.Models;

namespace CloudInfrastructureProvisioner.Resolver
{
    public class DependencyResolver
    {
        private enum NodeState { Unvisited, Visiting, Visited }

        public static List<ResourceDefinition> ResolveAndValidate(List<ResourceDefinition> resources)
        {
            var resourceMap = resources.ToDictionary(r => r.Id, r => r, StringComparer.OrdinalIgnoreCase);

            // 1. Check for missing dependencies
            foreach (var res in resources)
            {
                foreach (var dep in res.Dependencies)
                {
                    if (!resourceMap.ContainsKey(dep))
                    {
                        throw new DependencyException(
                            $"Resource dependency error: Resource '{res.Id}' depends on '{dep}', which is not defined in the configuration."
                        );
                    }
                }
            }

            // 2. Perform cycle detection
            var states = resources.ToDictionary(r => r.Id, _ => NodeState.Unvisited, StringComparer.OrdinalIgnoreCase);
            var cycleStack = new List<string>();

            foreach (var res in resources)
            {
                if (states[res.Id] == NodeState.Unvisited)
                {
                    if (DetectCycle(res.Id, resourceMap, states, cycleStack))
                    {
                        var cyclePath = string.Join(" -> ", cycleStack);
                        throw new CircularDependencyException($"Circular reference cycle detected: {cyclePath}");
                    }
                }
            }

            // 3. Return a linear sequence using Kahn's topological sort
            return TopologicalSort(resources, resourceMap);
        }

        private static bool DetectCycle(
            string currentId, 
            Dictionary<string, ResourceDefinition> map, 
            Dictionary<string, NodeState> states, 
            List<string> stack)
        {
            states[currentId] = NodeState.Visiting;
            stack.Add(currentId);

            foreach (var dep in map[currentId].Dependencies)
            {
                if (states[dep] == NodeState.Visiting)
                {
                    stack.Add(dep); // Add boundary node to complete cycle representation
                    return true;
                }

                if (states[dep] == NodeState.Unvisited)
                {
                    if (DetectCycle(dep, map, states, stack))
                    {
                        return true;
                    }
                }
            }

            stack.RemoveAt(stack.Count - 1);
            states[currentId] = NodeState.Visited;
            return false;
        }

        private static List<ResourceDefinition> TopologicalSort(
            List<ResourceDefinition> resources, 
            Dictionary<string, ResourceDefinition> map)
        {
            var inDegree = resources.ToDictionary(r => r.Id, _ => 0, StringComparer.OrdinalIgnoreCase);
            var adjList = resources.ToDictionary(r => r.Id, _ => new List<string>(), StringComparer.OrdinalIgnoreCase);

            foreach (var res in resources)
            {
                foreach (var dep in res.Dependencies)
                {
                    adjList[dep].Add(res.Id);
                    inDegree[res.Id]++;
                }
            }

            var queue = new Queue<string>();
            foreach (var node in inDegree.Where(kv => kv.Value == 0))
            {
                queue.Enqueue(node.Key);
            }

            var order = new List<ResourceDefinition>();
            while (queue.Count > 0)
            {
                var current = queue.Dequeue();
                order.Add(map[current]);

                foreach (var neighbor in adjList[current])
                {
                    inDegree[neighbor]--;
                    if (inDegree[neighbor] == 0)
                    {
                        queue.Enqueue(neighbor);
                    }
                }
            }

            return order;
        }
    }
}
```

#### 4. Execution Engine (`CloudInfrastructureProvisioner.Engine`)

The deployment execution engine schedules operations on a non-blocking asynchronous task graph. Rather than processing linear batches step-by-step, **each node starts execution immediately once its pre-requisites are fulfilled**.

```csharp
using System;
using System.Collections.Concurrent;
using System.Collections.Generic;
using System.Linq;
using System.Threading.Tasks;
using CloudInfrastructureProvisioner.Models;

namespace CloudInfrastructureProvisioner.Engine
{
    public interface IResourceExecutor
    {
        Task<DeploymentResult> ExecuteDeploymentAsync(ResourceDefinition resource);
    }

    public class ExecutionEngine
    {
        private readonly IResourceExecutor _executor;

        public ExecutionEngine(IResourceExecutor executor)
        {
            _executor = executor ?? throw new ArgumentNullException(nameof(executor));
        }

        public async Task<Dictionary<string, DeploymentResult>> ExecuteAsync(List<ResourceDefinition> resources)
        {
            var resourceMap = resources.ToDictionary(r => r.Id, r => r, StringComparer.OrdinalIgnoreCase);
            var activeDeploymentTasks = new ConcurrentDictionary<string, Task<DeploymentResult>>(StringComparer.OrdinalIgnoreCase);

            // A local recursive scheduler that maps the task dependency hierarchy
            Task<DeploymentResult> GetOrCreateTask(string id)
            {
                return activeDeploymentTasks.GetOrAdd(id, targetId =>
                {
                    var targetResource = resourceMap[targetId];

                    // Kick off dependency execution first, creating a task coordinate chain
                    return Task.Run(async () =>
                    {
                        if (targetResource.Dependencies.Count > 0)
                        {
                            var trackingTasks = targetResource.Dependencies
                                .Select(GetOrCreateTask)
                                .ToArray();

                            // Non-blocking wait for all dependencies to deploy
                            var dependencyResults = await Task.WhenAll(trackingTasks);

                            // Check for upstream failures
                            var failedDependency = dependencyResults.FirstOrDefault(d => !d.Success);
                            if (failedDependency != null)
                            {
                                return new DeploymentResult(
                                    targetId,
                                    targetResource.Type,
                                    Success: false,
                                    Duration: TimeSpan.Zero,
                                    OutputProperties: new(),
                                    ErrorMessage: $"Cancelled: Upstream dependency error on '{failedDependency.ResourceId}'"
                                );
                            }
                        }

                        // Run deployment once dependencies are verified
                        return await _executor.ExecuteDeploymentAsync(targetResource);
                    });
                });
            }

            // Start processing all roots in parallel
            var overallTasks = resources.Select(r => GetOrCreateTask(r.Id)).ToArray();
            await Task.WhenAll(overallTasks);

            // Fetch compiled outputs
            return activeDeploymentTasks.ToDictionary(
                kv => kv.Key, 
                kv => kv.Value.Result, 
                StringComparer.OrdinalIgnoreCase
            );
        }
    }
}
```

