### Verification and Simulation Execution

This `Program.cs` file demonstrates the components in action. It defines:
1. **Mock Execution Engine**: Simulates external cloud latency with varied execution speeds per resource type.
2. **Valid Complex Topology Run**: Simulates parallel deployment (e.g., Subnet & Database running concurrently).
3. **Circular Graph Resolution Error Demonstration**: Visualizes graph evaluation failure on cycle scenarios.

```csharp
using System;
using System.Collections.Generic;
using System.Threading.Tasks;
using CloudInfrastructureProvisioner.Engine;
using CloudInfrastructureProvisioner.Models;
using CloudInfrastructureProvisioner.Parser;
using CloudInfrastructureProvisioner.Resolver;

namespace CloudInfrastructureProvisioner
{
    public class MockCloudExecutor : IResourceExecutor
    {
        private static readonly object LogLock = new();

        public async Task<DeploymentResult> ExecuteDeploymentAsync(ResourceDefinition resource)
        {
            Log($"[START] Initializing provisioning for '{resource.Id}' ({resource.Type})...", ConsoleColor.Cyan);

            // Simulate realistic, variable cloud networking latency for resource creation
            int latencyMs = resource.Type.ToLower() switch
            {
                "virtualnetwork" => 1500,
                "subnet" => 750,
                "database" => 2000,
                "virtualmachine" => 1800,
                "appservice" => 1000,
                _ => 500
            };

            await Task.Delay(latencyMs);

            var generatedOutputs = new Dictionary<string, object>(StringComparer.OrdinalIgnoreCase);
            foreach (var key in resource.Properties.Keys)
            {
                generatedOutputs[$"{resource.Id}.{key}"] = resource.Properties[key];
            }
            generatedOutputs[$"{resource.Id}.Status"] = "ProvisionedOnline";

            Log($"[SUCCESS] Done provisioning '{resource.Id}' in {latencyMs}ms", ConsoleColor.Green);

            return new DeploymentResult(
                resource.Id,
                resource.Type,
                Success: true,
                Duration: TimeSpan.FromMilliseconds(latencyMs),
                OutputProperties: generatedOutputs
            );
        }

        public static void Log(string message, ConsoleColor color = ConsoleColor.Gray)
        {
            lock (LogLock)
            {
                Console.ForegroundColor = color;
                Console.WriteLine($"[{DateTime.Now:HH:mm:ss.fff}] {message}");
                Console.ResetColor();
            }
        }
    }

    internal class Program
    {
        static async Task Main(string[] args)
        {
            Console.Title = "Automated Cloud Infrastructure Provisioner";

            // -------------------------------------------------------------
            // SCENARIO A: Valid asynchronous multi-branch execution topology
            // -------------------------------------------------------------
            string validTopologyJson = @"
            [
                {
                    ""Id"": ""vnet-prod"",
                    ""Type"": ""VirtualNetwork"",
                    ""Properties"": { ""AddressSpace"": ""10.0.0.0/16"" },
                    ""Dependencies"": []
                },
                {
                    ""Id"": ""subnet-backend"",
                    ""Type"": ""Subnet"",
                    ""Properties"": { ""CidrRange"": ""10.0.1.0/24"" },
                    ""Dependencies"": [""vnet-prod""]
                },
                {
                    ""Id"": ""db-sqlserver"",
                    ""Type"": ""Database"",
                    ""Properties"": { ""Edition"": ""Premium"", ""SizeGb"": 250 },
                    ""Dependencies"": [""vnet-prod""]
                },
                {
                    ""Id"": ""vm-appserver"",
                    ""Type"": ""VirtualMachine"",
                    ""Properties"": { ""Sku"": ""Standard_D4_v5"" },
                    ""Dependencies"": [""vnet-prod"", ""subnet-backend""]
                },
                {
                    ""Id"": ""gateway-api"",
                    ""Type"": ""AppService"",
                    ""Properties"": { ""AutoScale"": true },
                    ""Dependencies"": [""db-sqlserver"", ""vm-appserver""]
                }
            ]";

            MockCloudExecutor.Log("--- INITIATING TOPOLOGY DEPLOYMENT SCENARIO A (Valid Parallel Spec) ---", ConsoleColor.White);

            try
            {
                // 1. Declarative parsing
                var resources = ResourceParser.Parse(validTopologyJson);

                // 2. Dependency validation and topological confirmation
                var sortedList = DependencyResolver.ResolveAndValidate(resources);

                MockCloudExecutor.Log("\nValidated Dependency Plan (Topological Order):", ConsoleColor.Yellow);
                foreach (var item in sortedList)
                {
                    Console.WriteLine($"  -> {item.Id} (Depends on: [{string.Join(", ", item.Dependencies)}])");
                }
                Console.WriteLine();

                // 3. Parallel asynchronous execution deployment
                var engine = new ExecutionEngine(new MockCloudExecutor());

                MockCloudExecutor.Log("Starting Parallel Infrastructure Orchestration Execution Engine...", ConsoleColor.Yellow);
                var executionResults = await engine.ExecuteAsync(resources);

                MockCloudExecutor.Log("\n--- DEPLOYMENT REPORT SUMMARY ---", ConsoleColor.White);
                foreach (var resId in executionResults.Keys)
                {
                    var report = executionResults[resId];
                    var statusColor = report.Success ? ConsoleColor.DarkGreen : ConsoleColor.DarkRed;
                    MockCloudExecutor.Log($"Resource: {report.ResourceId,-15} | Status: {(report.Success ? "ONLINE" : "FAILED"),-8} | Duration: {report.Duration.TotalSeconds:F2}s", statusColor);
                }
            }
            catch (Exception ex)
            {
                MockCloudExecutor.Log($"Scenario A Error: {ex.Message}", ConsoleColor.Red);
            }

            // -------------------------------------------------------------
            // SCENARIO B: Cyclic dependency loop detection validation
            // -------------------------------------------------------------
            Console.WriteLine("\n");
            MockCloudExecutor.Log("--- INITIATING VALIDATION SCENARIO B (Cyclic Fail Demonstration) ---", ConsoleColor.White);

            string cyclicTopologyJson = @"
            [
                {
                    ""Id"": ""module-A"",
                    ""Type"": ""VirtualNetwork"",
                    ""Dependencies"": [""module-C""]
                },
                {
                    ""Id"": ""module-B"",
                    ""Type"": ""Database"",
                    ""Dependencies"": [""module-A""]
                },
                {
                    ""Id"": ""module-C"",
                    ""Type"": ""VirtualMachine"",
                    ""Dependencies"": [""module-B""]
                }
            ]";

            try
            {
                var cyclicResources = ResourceParser.Parse(cyclicTopologyJson);
                DependencyResolver.ResolveAndValidate(cyclicResources);
            }
            catch (CircularDependencyException ex)
            {
                MockCloudExecutor.Log($"Expected Cyclic Validation Successful! Raised Exception:\n  {ex.Message}", ConsoleColor.Magenta);
            }
            catch (Exception ex)
            {
                MockCloudExecutor.Log($"Unexpected Failure Mode: {ex.Message}", ConsoleColor.Red);
            }

            Console.WriteLine("\nSystem simulation execution completed.");
        }
    }
}
